package com.example.lending.application.service;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.out.CreditCheckPort;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.LoadReservationPort;
import com.example.lending.application.port.out.RemoveReservationPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.adapter.out.persistence.BookJpaEntity;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.BookStatus;
import com.example.lending.domain.Loan;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import com.example.lending.domain.Reservation;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Objects;
import java.util.Optional;

@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadReservationPort loadReservationPort;
    private final RemoveReservationPort removeReservationPort;
    private final CreditCheckPort creditCheckPort;

    public LoanBookService(LoadMemberPort loadMemberPort, LoadLoanPort loadLoanPort, LoadBookPort loadBookPort,
                           SaveBookPort saveBookPort, SaveLoanPort saveLoanPort,
                           LoadReservationPort loadReservationPort, RemoveReservationPort removeReservationPort,
                           CreditCheckPort creditCheckPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
        this.loadReservationPort = loadReservationPort;
        this.removeReservationPort = removeReservationPort;
        this.creditCheckPort = creditCheckPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        Member member = loadMemberPort.loadMember(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        member.ensureCanBorrow(loadLoanPort.countActiveLoans(member.getId()));

        BookJpaEntity raw = loadBookPort.findRaw(command.bookId());
        if (raw == null) {
            throw new BookNotFoundException(command.bookId());
        }
        Book book = loadBookPort.loadBook(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        book.ensureLoanable();
        ReservationQueue queue = new ReservationQueue(loadReservationPort.loadActiveReservations(book.getId()));
        Optional<Reservation> claimed = queue.claimFor(command.memberId());
        CreditCheck creditCheck = creditCheckPort.check(member.getId(), member.getName());
        LocalDate loanedAt = Objects.requireNonNullElseGet(command.loanedAt(), LocalDate::now);
        Loan loan = Loan.start(book.getId(), command.memberId(), loanedAt, creditCheck);
        book.setStatus(BookStatus.ON_LOAN);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        claimed.ifPresent(reservation -> removeReservationPort.removeReservation(reservation.getId()));
        return loan;
    }
}
package com.example.lending.adapter.in.web;

import com.example.lending.adapter.out.persistence.BookJpaEntity;
import com.example.lending.adapter.out.persistence.BookJpaRepository;
import com.example.lending.application.port.in.DiscardBookUseCase;
import com.example.lending.application.port.in.DiscardBookUseCase.DiscardBookCommand;
import com.example.lending.application.port.in.RegisterBookUseCase;
import com.example.lending.application.port.in.RegisterBookUseCase.RegisterBookCommand;
import com.example.lending.application.port.in.SearchBooksUseCase;
import com.example.lending.application.port.in.SearchBooksUseCase.SearchBooksQuery;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books")
public class BookController {

    private final RegisterBookUseCase registerBookUseCase;
    private final SearchBooksUseCase searchBooksUseCase;
    private final DiscardBookUseCase discardBookUseCase;
    private final BookJpaRepository bookJpaRepository;

    public BookController(RegisterBookUseCase registerBookUseCase,
                          SearchBooksUseCase searchBooksUseCase,
                          DiscardBookUseCase discardBookUseCase,
                          BookJpaRepository bookJpaRepository) {
        this.registerBookUseCase = registerBookUseCase;
        this.searchBooksUseCase = searchBooksUseCase;
        this.discardBookUseCase = discardBookUseCase;
        this.bookJpaRepository = bookJpaRepository;
    }

    @GetMapping
    public List<BookResponse> searchBooks(@RequestParam String title) {
        return searchBooksUseCase.searchBooks(new SearchBooksQuery(title)).stream()
                .map(BookResponse::from)
                .toList();
    }

    @GetMapping("/{id}")
    public BookJpaEntity getBook(@PathVariable UUID id) {
        return bookJpaRepository.findById(id).orElseThrow(() -> new BookNotFoundException(id));
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public BookResponse registerBook(@RequestBody RegisterBookRequest request) {
        Book book = registerBookUseCase.registerBook(new RegisterBookCommand(request.title()));
        return BookResponse.from(book);
    }

    @PostMapping("/{bookId}/discard")
    public BookResponse discardBook(@PathVariable UUID bookId) {
        Book book = discardBookUseCase.discardBook(new DiscardBookCommand(bookId));
        return BookResponse.from(book);
    }
}
